void PolicyHostAsyncWaiter::GetPolicies(
    std::string* out_policies) {
  base::RunLoop loop;
  proxy_->GetPolicies(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_policies
,
             const std::string& policies) {*out_policies = std::move(policies);
            loop->Quit();
          },
          &loop,
          out_policies));
  loop.Run();
}

std::string PolicyHostAsyncWaiter::GetPolicies(
    ) {
  std::string async_wait_result;
  GetPolicies(&async_wait_result);
  return async_wait_result;
}

void PolicyHostAsyncWaiter::ReportCompliance(
    const std::string& request, std::string* out_response) {
  base::RunLoop loop;
  proxy_->ReportCompliance(std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_response
,
             const std::string& response) {*out_response = std::move(response);
            loop->Quit();
          },
          &loop,
          out_response));
  loop.Run();
}

std::string PolicyHostAsyncWaiter::ReportCompliance(
    const std::string& request) {
  std::string async_wait_result;
  ReportCompliance(std::move(request),&async_wait_result);
  return async_wait_result;
}




