void PolicyInstanceAsyncWaiter::Init(
    ::mojo::PendingRemote<PolicyHost> host_remote) {
  base::RunLoop loop;
  proxy_->Init(std::move(host_remote),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void PolicyInstanceAsyncWaiter::OnCommandReceived(
    const std::string& command, CommandResultType* out_result) {
  base::RunLoop loop;
  proxy_->OnCommandReceived(std::move(command),
      base::BindOnce(
          [](base::RunLoop* loop,
             CommandResultType* out_result
,
             CommandResultType result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

CommandResultType PolicyInstanceAsyncWaiter::OnCommandReceived(
    const std::string& command) {
  CommandResultType async_wait_result;
  OnCommandReceived(std::move(command),&async_wait_result);
  return async_wait_result;
}






